#include "image_core.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

static unsigned checks;
static const char*phase="start";
static size_t peak_all;
#define CHECK(x) do{++checks;if(!(x)){fprintf(stderr,"FAIL %s:%d %s\n",__FILE__,__LINE__,#x);exit(1);}}while(0)
typedef struct{size_t live,peak,calls,limit;long fail;int persistent;} Memory;
typedef union{size_t bytes;long double alignment;} Block;
static void*allocate(void*context,size_t n){Memory*m=context;Block*b;size_t at=m->calls++;if(m->fail>=0&&at>=(size_t)m->fail&&(m->persistent||at==(size_t)m->fail))return 0;if(n>m->limit-m->live)return 0;b=malloc(sizeof(*b)+n);if(!b)return 0;b->bytes=n;m->live+=n;if(m->live>m->peak)m->peak=m->live;if(m->live>peak_all)peak_all=m->live;return b+1;}
static void release(void*context,void*p){Memory*m=context;Block*b;if(!p)return;b=(Block*)p-1;CHECK(m->live>=b->bytes);m->live-=b->bytes;free(b);}
static void setup(IEDoc*d,Memory*m,int w,int h){memset(m,0,sizeof(*m));m->limit=18u*1024u*1024u;m->fail=-1;CHECK(ie_init(d,allocate,release,m,w,h));}
static void cleanup(IEDoc*d,Memory*m){m->fail=-1;ie_destroy(d);CHECK(m->live==0);}
static unsigned min(unsigned a,unsigned b){return a<b?a:b;}
static uint32_t over(uint32_t dst,uint32_t src,unsigned opacity){unsigned sa=((src>>24)*opacity+127)/255,da=dst>>24,oa,k;uint32_t out;if(!sa)return dst;if(sa==255)return src;if(!da)return(src&0xffffffu)|(sa<<24);oa=sa+(da*(255-sa)+127)/255;out=oa<<24;for(k=0;k<24;k+=8){unsigned sc=(src>>k)&255,dc=(dst>>k)&255,c=(sc*sa+(dc*da*(255-sa)+127)/255+oa/2)/oa;out|=min(255,c)<<k;}return out;}
static void seed(IEDoc*d){size_t i,n=(size_t)d->current.width*d->current.height;for(i=0;i<n;i++)d->current.layers[d->current.active].pixels[i]=IE_RGBA((i*37+5)%256,(i*79+13)%256,(i*17+211)%256,(i%4)*85);}
static void select_mask(IEDoc*d,int x,int y,int w,int h){static const unsigned char coverage[]={0,1,64,128,192,254,255};int xx,yy;size_t n=(size_t)d->current.width*d->current.height;ie_select(d,x,y,x+w-1,y+h-1);d->current.selection_mask=allocate(d->memory_context,n);CHECK(d->current.selection_mask!=0);memset(d->current.selection_mask,0,n);for(yy=0;yy<h;yy++)for(xx=0;xx<w;xx++)d->current.selection_mask[(size_t)(y+yy)*d->current.width+x+xx]=coverage[(xx+yy*w)%7];}
static void expected_move(uint32_t*out,const uint32_t*original,const uint8_t*mask,int w,int h,int sx,int sy,int sw,int sh,int tx,int ty,int cut){int x,y;memcpy(out,original,(size_t)w*h*4);if(cut)for(y=0;y<sh;y++)for(x=0;x<sw;x++){size_t at=(size_t)(sy+y)*w+sx+x;unsigned a=mask?mask[at]:255,aa;if(!a)continue;aa=((out[at]>>24)*(255-a)+127)/255;out[at]=aa?(out[at]&0xffffffu)|(aa<<24):0;}
 for(y=0;y<sh;y++)for(x=0;x<sw;x++){int xx=tx+x,yy=ty+y;size_t at,from=(size_t)(sy+y)*w+sx+x;unsigned a=mask?mask[from]:255;if(xx<0||yy<0||xx>=w||yy>=h||!a)continue;at=(size_t)yy*w+xx;if(cut&&sx==tx&&sy==ty)out[at]=original[from];else out[at]=over(out[at],original[from],a);}}
static void exact(IEDoc*d,const uint32_t*expected){for(size_t i=0;i<(size_t)d->current.width*d->current.height;i++)if(d->current.layers[d->current.active].pixels[i]!=expected[i]){fprintf(stderr,"phase=%s pixel=%zu actual=%08x expected=%08x\n",phase,i,d->current.layers[d->current.active].pixels[i],expected[i]);CHECK(0);break;}CHECK(1);}
static void test_moves(int masked){enum{W=31,H=23,SX=3,SY=5,SW=12,SH=9};IEDoc d;Memory m;uint32_t original[W*H],expected[W*H];uint8_t mask[W*H];int pos[][2]={{11,5},{5,8},{-7,-3},{31,23},{-15,24},{2,4},{SX,SY}},x=SX,y=SY,cycle,i;
 setup(&d,&m,W,H);seed(&d);memcpy(original,d.current.layers[0].pixels,sizeof(original));if(masked){select_mask(&d,SX,SY,SW,SH);memcpy(mask,d.current.selection_mask,sizeof(mask));}else ie_select(&d,SX,SY,SX+SW-1,SY+SH-1);
 for(cycle=0;cycle<30;cycle++)for(i=0;i<7;i++){int nx=pos[i][0],ny=pos[i][1];CHECK(ie_translate_selection(&d,nx-x,ny-y));expected_move(expected,original,masked?mask:0,W,H,SX,SY,SW,SH,nx,ny,1);exact(&d,expected);CHECK(ie_undo(&d));expected_move(expected,original,masked?mask:0,W,H,SX,SY,SW,SH,x,y,1);exact(&d,expected);CHECK(ie_redo(&d));expected_move(expected,original,masked?mask:0,W,H,SX,SY,SW,SH,nx,ny,1);exact(&d,expected);x=nx;y=ny;}
 exact(&d,original);CHECK(ie_translate_selection(&d,10,0));CHECK(ie_selection_delete(&d));expected_move(expected,original,masked?mask:0,W,H,SX,SY,SW,SH,W,H,1);exact(&d,expected);CHECK(ie_undo(&d));CHECK(ie_translate_selection(&d,-10,0));exact(&d,original);
 cleanup(&d,&m);
}
static void test_clipboard(void){IEDoc d,temporary;Memory m;IERect r;uint32_t original[20*18],background[20*18],expected[20*18];size_t i;uint8_t alpha[20*18];setup(&d,&m,20,18);seed(&d);select_mask(&d,1,2,7,5);memcpy(original,d.current.layers[0].pixels,sizeof(original));memcpy(alpha,d.current.selection_mask,sizeof(alpha));CHECK(ie_selection_copy(&d));CHECK(ie_clipboard_available(&d));CHECK(ie_clipboard_bounds(&d,&r)&&r.w==7&&r.h==5);CHECK(ie_translate_selection(&d,3,4));CHECK(ie_selection_copy(&d));CHECK(ie_new(&d,20,18,IE_RGBA(41,73,27,198)));CHECK(ie_clipboard_available(&d));for(i=0;i<20*18;i++)background[i]=d.current.layers[0].pixels[i];CHECK(ie_selection_paste(&d,10,7));CHECK(ie_translate_selection(&d,-9,-5));memcpy(expected,background,sizeof(expected));for(int y=0;y<5;y++)for(int x=0;x<7;x++){size_t at=(size_t)(y+2)*20+x+1;expected[at]=over(background[at],original[at],alpha[at]);}exact(&d,expected);
 CHECK(ie_selection_delete(&d));exact(&d,background);CHECK(ie_undo(&d));exact(&d,expected);CHECK(ie_selection_cut(&d));exact(&d,background);CHECK(ie_clipboard_available(&d));CHECK(ie_selection_paste(&d,1,2));exact(&d,expected);ie_clipboard_clear(&d);CHECK(!ie_clipboard_available(&d));CHECK(ie_translate_selection(&d,9,5));CHECK(ie_translate_selection(&d,-9,-5));exact(&d,expected);CHECK(ie_selection_copy(&d));
 CHECK(ie_init(&temporary,allocate,release,&m,12,11));CHECK(ie_clipboard_transfer(&temporary,&d));CHECK(!ie_clipboard_available(&d));CHECK(ie_clipboard_available(&temporary));ie_destroy(&d);d=temporary;CHECK(ie_selection_paste(&d,1,2));CHECK(ie_undo(&d));CHECK(ie_redo(&d));cleanup(&d,&m);
}
typedef struct{uint8_t*bytes;size_t size,pos,capacity;} Stream;
static size_t write_stream(void*context,const void*data,size_t n){Stream*s=context;if(n>s->capacity-s->size)return 0;memcpy(s->bytes+s->size,data,n);s->size+=n;return n;}
static size_t read_stream(void*context,void*data,size_t n){Stream*s=context;if(n>s->size-s->pos)n=s->size-s->pos;memcpy(data,s->bytes+s->pos,n);s->pos+=n;return n;}
static void test_native_imports(void){IEDoc d;Memory m;uint8_t data[8192];Stream out={data,0,0,sizeof(data)};IERect r;setup(&d,&m,16,12);seed(&d);ie_select(&d,2,2,6,5);CHECK(ie_selection_copy(&d));CHECK(ie_save_project(&d,write_stream,&out));CHECK(ie_new(&d,9,8,0));CHECK(ie_load_project(&d,read_stream,&out));CHECK(ie_clipboard_bounds(&d,&r)&&r.w==5&&r.h==4);CHECK(ie_selection_paste(&d,0,0));out.size=out.pos=0;CHECK(ie_save_bmp(&d,write_stream,&out));CHECK(ie_new(&d,3,3,0));CHECK(ie_load_bmp(&d,read_stream,&out));CHECK(ie_clipboard_bounds(&d,&r)&&r.w==5&&r.h==4);CHECK(ie_selection_paste(&d,9,7));cleanup(&d,&m);}
static int operation(IEDoc*d,int op){switch(op){case 0:return ie_translate_selection(d,6,4);case 1:return ie_selection_copy(d);case 2:return ie_selection_cut(d);case 3:return ie_selection_paste(d,11,9);case 4:return ie_selection_delete(d);default:return ie_translate_selection(d,-6,-4);}}
static void test_failures(void){int op,at,persistent;for(persistent=0;persistent<2;persistent++)for(op=0;op<6;op++)for(at=0;at<18;at++){IEDoc d;Memory m;uint32_t saved[24*20];IESelectionPixels*clipboard;IERect selected;int ok;setup(&d,&m,24,20);seed(&d);select_mask(&d,1,2,8,7);CHECK(ie_selection_copy(&d));if(op==5||op==4)CHECK(ie_translate_selection(&d,6,4));memcpy(saved,d.current.layers[0].pixels,sizeof(saved));clipboard=d.clipboard;selected=d.current.selection;m.fail=(long)m.calls+at;m.persistent=persistent;ok=operation(&d,op);if(!ok){exact(&d,saved);CHECK(d.clipboard==clipboard);CHECK(!memcmp(&selected,&d.current.selection,sizeof(selected)));}m.fail=-1;cleanup(&d,&m);}}
static void test_stamp(void){IEDoc d;Memory m;uint8_t mask[6]={255,128,0,64,192,255};setup(&d,&m,10,8);CHECK(ie_new(&d,10,8,0));CHECK(ie_begin(&d));ie_mask_stamp(&d,2,3,mask,3,2,3,IE_RGBA(80,140,200,255),100);CHECK(d.current.layers[0].pixels[3*10+2]==IE_RGBA(80,140,200,255));CHECK((d.current.layers[0].pixels[3*10+3]>>24)==128);CHECK(d.current.layers[0].pixels[3*10+4]==0);CHECK(ie_undo(&d));CHECK(d.current.layers[0].pixels[3*10+2]==0);CHECK(ie_begin(&d));ie_mask_stamp(&d,INT_MIN,INT_MAX,mask,3,2,3,0xffffffff,100);CHECK(d.current.layers[0].pixels[0]==0);ie_mask_stamp(&d,-1,-1,mask,3,2,3,0xffffffff,100);CHECK((d.current.layers[0].pixels[0]>>24)==192);cleanup(&d,&m);}
static void test_edit_history(void){
 IEDoc d;Memory m;uint32_t original[30*24],moved[30*24];IEBrush brush={IE_RGBA(200,40,130,255),5,100,100,0,0,0};
 setup(&d,&m,30,24);seed(&d);memcpy(original,d.current.layers[0].pixels,sizeof(original));select_mask(&d,3,4,10,9);CHECK(ie_translate_selection(&d,5,3));memcpy(moved,d.current.layers[0].pixels,sizeof(moved));
 CHECK(ie_brush_begin(&d));CHECK(ie_brush(&d,11,10,14,12,&brush));ie_commit(&d);CHECK(ie_undo(&d));exact(&d,moved);CHECK(ie_redo(&d));CHECK(ie_undo(&d));CHECK(ie_translate_selection(&d,-5,-3));exact(&d,original);
 CHECK(ie_translate_selection(&d,5,3));CHECK(ie_brush_begin(&d));CHECK(ie_brush(&d,11,10,14,12,&brush));CHECK(ie_cancel(&d));exact(&d,moved);CHECK(ie_translate_selection(&d,-5,-3));exact(&d,original);
 CHECK(ie_translate_selection(&d,5,3));CHECK(ie_adjust(&d,20,10,-20,110,90,125,0));CHECK(ie_undo(&d));exact(&d,moved);CHECK(ie_translate_selection(&d,-5,-3));exact(&d,original);
 cleanup(&d,&m);
}
static size_t large_peak;
static void test_large(void){IEDoc d;Memory m;void*view;int i;setup(&d,&m,1100,610);view=allocate(&m,2u*1024u*1024u);CHECK(view!=0);seed(&d);ie_select(&d,0,0,1099,609);for(i=0;i<20;i++){CHECK(ie_translate_selection(&d,1,0));CHECK(ie_translate_selection(&d,-1,0));CHECK(ie_undo(&d));CHECK(ie_redo(&d));CHECK(m.live<=m.limit);}large_peak=m.peak;release(&m,view);cleanup(&d,&m);}
int main(void){phase="rectangle";test_moves(0);phase="masked";test_moves(1);phase="clipboard";test_clipboard();phase="imports";test_native_imports();phase="failures";test_failures();phase="stamp";test_stamp();phase="edit-history";test_edit_history();phase="large";test_large();printf("{\"passed\":true,\"checks\":%u,\"allocationFailureScenarios\":216,\"repeatMoveCycles\":420,\"largeCycleReservedViewBytes\":2097152,\"largePeakBytes\":%zu,\"peakBytes\":%zu}\n",checks,large_peak,peak_all);return 0;}
